LANGS = {"en": EN, "tr": TR, "de": DE, "es": ES, "fr": FR, "it": IT, "pt": PT, "ru": RU, "ja": JA, "zh": ZH}


def main():
    for code, d in LANGS.items():
        path = os.path.join(ROOT, "ui/js/i18n/%s.js" % code)
        text = open(path, encoding="utf-8").read()
        merged = dict(d)
        if code != "en":
            merged.setdefault("nav.upgraph", "Upgraph")
        lines = []
        for k, v in merged.items():
            if re.search(r'\n\s*"%s":' % re.escape(k), text):
                text = re.sub(r'(\n\s*"%s":\s*)"(?:[^"\\]|\\.)*"' % re.escape(k), lambda m: m.group(1) + json.dumps(v, ensure_ascii=False), text)
            else:
                lines.append("  %s: %s," % (json.dumps(k), json.dumps(v, ensure_ascii=False)))
        if lines:
            end = text.rstrip().rindex("}")
            body = text[:end].rstrip()
            if not body.endswith(","):
                body += ","
            text = body + "\n" + "\n".join(lines).rstrip(",") + "\n};\n"
        open(path, "w", encoding="utf-8").write(text)
        print(code, len(lines), "added")


if __name__ == "__main__":
    main()
